package dao;
import java.util.List;
import model.Employee;
import java.sql.SQLException;

/**
 * Defines the database operations for employees.
 * The service layer talks to this interface only, so the JDBC details stay in EmployeeDAOImpl.
 */
public interface EmployeeDAO {
    /**
     * Saves a new employee in the database.
     *
     * @param employee the employee to save (its id is not used, the database generates it)
     * @return the id generated by the database for the new employee
     * @throws SQLException if the insert fails, for example when the email already exists
     */
    int addEmployee(Employee employee) throws SQLException;

    /**
     * Gets every employee from the database.
     *
     * @return a list of all employees, empty if there are none
     * @throws SQLException if the database call fails
     */
    List<Employee> viewAllEmployees() throws SQLException;

    /**
     * Finds one employee by id.
     *
     * @param id the id of the employee to find
     * @return the employee, or null if no employee has this id
     * @throws SQLException if the database call fails
     */
    Employee findEmployee(int id) throws SQLException;

    /**
     * Changes the department of an employee.
     *
     * @param id the id of the employee to update
     * @param department the new department
     * @return true if the employee was updated, false if no employee has this id
     * @throws SQLException if the database call fails
     */
    boolean updateDepartment(int id,String department) throws SQLException;

    /**
     * Changes the salary of an employee.
     *
     * @param id the id of the employee to update
     * @param salary the new salary
     * @return true if the employee was updated, false if no employee has this id
     * @throws SQLException if the database call fails
     */
    boolean updateSalary(int id,double salary) throws SQLException;

    /**
     * Changes the email of an employee.
     *
     * @param id the id of the employee to update
     * @param email the new email
     * @return true if the employee was updated, false if no employee has this id
     * @throws SQLException if the database call fails, for example when the email already exists
     */
    boolean updateEmail(int id,String email) throws SQLException;

    /**
     * Changes the department, salary and email of an employee in one go.
     *
     * @param id the id of the employee to update
     * @param department the new department
     * @param salary the new salary
     * @param email the new email
     * @return true if the employee was updated, false if no employee has this id
     * @throws SQLException if the database call fails, for example when the email already exists
     */
    boolean updateAll(int id,String department,double salary,String email) throws SQLException;

    /**
     * Deletes an employee.
     *
     * @param id the id of the employee to delete
     * @return true if the employee was deleted, false if no employee has this id
     * @throws SQLException if the database call fails
     */
    boolean deleteEmployee(int id) throws SQLException;
}